import Image from 'next/image';
import HadiTechLogo from "./../../public/haditechlogo.svg"
import TagLogo from "./../../public/Name_Tag_Combined.svg"

export default function MainPage() {
  return (
    <header className="bg-gray-50 sticky top-0 z-50 border-1 border-gray-200 opacity-[0.9]">
      <nav className="mx-5 flex items-center justify-between px-6 py-4 border-t-1 border-gray-100" aria-label="Global">
         <div className="flex items-center space-x-1">
            <Image className="h-12 w-auto"
              priority
              src={HadiTechLogo}
              alt="Logo of Haadi Tech"
            />
          {/* <h4 className="ml-3 text-base/7 font-semibold text-[#004a8f] sm:text-1xl">THINK THE UNTHINKABLE</h4> */}
          <Image className="h-12 w-auto ml-4 pt-1"
            priority
            src={TagLogo}
            alt="Logo of Haadi Tech"
          />
        </div>
      
        <div className="hidden md:flex space-x-8 text-gray-700 font-medium">
          <div className="relative">
            <button type="button" className="flex items-center gap-x-1 font-bold border-[#004a8f] text-[#004a8f] border-b-3 w-15  text-center justify-center text-lg" aria-expanded="false">
              Home
            </button>
          </div>
          <div className="relative">
             <button type="button" className="flex items-center gap-x-1 font-bold  text-[#004a8f]  w-15  text-center justify-center text-lg" aria-expanded="false">
              Work
            </button>
          </div>
          <div className="relative">
             <button type="button" className="flex items-center gap-x-1 font-bold  text-[#004a8f]  w-15  text-center justify-center text-lg" aria-expanded="false">
              Services
            </button>
          </div>
          <div className="relative">
             <button type="button" className="flex items-center gap-x-1 font-bold  text-[#004a8f]  w-15  text-center justify-center text-lg" aria-expanded="false">
              Clients
            </button>
          </div>
        </div>
         <div className="relative">
             <button type="button" className="flex items-center gap-x-1 font-bold bg-[#004a8f] hover:bg-[#003366] text-[#ffffff]  w-50 h-13 rounded-2xl  text-center justify-center text-lg" aria-expanded="false">
              Contact Us
            </button>
          </div>
      </nav>
    </header>
  );
}
